/**
 * Agent 基类 — 所有 Agent 的抽象基类
 */

import { MessageBus, messageBus } from "../message-bus.js";
import {
  AgentRole,
  Message,
  MessageType,
  createMessage,
} from "../models/task.js";
import { getAgentLogger } from "../utils/logger.js";

export abstract class BaseAgent {
  abstract readonly role: AgentRole;

  protected bus: MessageBus;
  protected log: ReturnType<typeof getAgentLogger>;
  private running = false;
  private loopPromise: Promise<void> | null = null;
  private abortController: AbortController | null = null;

  constructor(bus?: MessageBus) {
    this.bus = bus ?? messageBus;
    this.log = getAgentLogger("agent");
  }

  // ── 生命周期 ──────────────────────────────────

  async start(): Promise<void> {
    this.bus.register(this.role);
    this.running = true;
    this.abortController = new AbortController();
    this.log.info("Agent 启动");
    await this.onStart();
    this.loopPromise = this.messageLoop();
  }

  async stop(): Promise<void> {
    this.running = false;
    this.abortController?.abort();
    try {
      await this.loopPromise;
    } catch {
      // ignore cancellation
    }
    await this.onStop();
    this.bus.unregister(this.role);
    this.log.info("Agent 已停止");
  }

  protected async onStart(): Promise<void> {}
  protected async onStop(): Promise<void> {}

  // ── 消息循环 ──────────────────────────────────

  private async messageLoop(): Promise<void> {
    while (this.running) {
      try {
        const message = await this.bus.receive(this.role, 500);
        if (message) {
          await this.handleMessage(message);
        }
      } catch (err) {
        if (!this.running) break;
        this.log.error(`消息循环异常: ${String(err)}`);
      }
    }
  }

  private async handleMessage(message: Message): Promise<void> {
    try {
      this.log.debug(`收到消息 [${message.msgType}] 来自 [${message.sender}]`);
      await this.processMessage(message);
    } catch (err) {
      this.log.error(`处理消息失败: ${message.id} — ${String(err)}`);
      this.bus.reply(message, "error", {
        error: `消息处理异常: ${String(err)}`,
        messageId: message.id,
      });
    }
  }

  // ── 抽象接口 ──────────────────────────────────

  abstract processMessage(message: Message): Promise<void>;

  // ── 便捷方法 ──────────────────────────────────

  async sendTaskResult(
    original: Message,
    result: Record<string, unknown>,
    status = "completed"
  ): Promise<void> {
    this.bus.reply(original, "task_result", { status, result });
  }

  async sendError(original: Message, error: string): Promise<void> {
    this.bus.reply(original, "error", { error });
  }

  async requestReview(
    taskId: string,
    content: Record<string, unknown>,
    reviewer: AgentRole = "tester"
  ): Promise<Message | null> {
    const msg = createMessage({
      msgType: "review_request",
      sender: this.role,
      receiver: reviewer,
      taskId,
      content,
    });
    return this.bus.sendAndWait(msg);
  }

  get isRunning(): boolean {
    return this.running;
  }
}

/**
 * DeveloperAgent — 代码编写与实现
 */

import { mkdirSync, writeFileSync } from "fs";
import { resolve, dirname } from "path";
import { BaseAgent } from "./base.js";
import { MessageBus } from "../message-bus.js";
import { LLMService, llmService } from "../services/llm.js";
import { AgentRole, Message, MessageType } from "../models/task.js";
import { ragIndex } from "../services/rag.js";

const DEVELOPER_SYSTEM_PROMPT = `你是一个资深软件工程师。根据任务描述和接口规范生成高质量的生产级代码。

## 代码要求
1. 完整的类型标注
2. 完善的错误处理和输入验证
3. 清晰的 JSDoc / docstring 注释
4. 遵循语言最佳实践
5. 代码可直接运行

## 输出格式
返回 JSON：
{
  "filename": "建议的文件名",
  "language": "typescript|python|go",
  "code": "完整的代码内容",
  "description": "代码简要说明",
  "dependencies": ["需要的依赖包列表"],
  "entry_point": "入口函数/类名",
  "test_hints": ["关键测试点"]
}
请直接返回 JSON。`;

interface DevelopResult {
  filename: string;
  language: string;
  code: string;
  description: string;
  dependencies: string[];
  entryPoint?: string;
}

export class DeveloperAgent extends BaseAgent {
  readonly role: AgentRole = "developer";
  private llm: LLMService;
  private outputDir: string;

  constructor(bus?: MessageBus, llm?: LLMService, outputDir = "./output") {
    super(bus);
    this.llm = llm ?? llmService;
    this.outputDir = outputDir;
    mkdirSync(this.outputDir, { recursive: true });
  }

  async processMessage(message: Message): Promise<void> {
    if (message.msgType === "task_assign") {
      await this.handleDevTask(message);
    } else if (message.msgType === "review_response") {
      await this.handleReviewFeedback(message);
    } else {
      await this.sendError(message, `未知消息类型: ${message.msgType}`);
    }
  }

  private async handleDevTask(message: Message): Promise<void> {
    const taskData = (message.content["task"] as Record<string, unknown>) ?? {};
    const language = (message.content["language"] as string) ?? "typescript";
    const title = (taskData["title"] as string) ?? "未命名任务";
    const description = (taskData["description"] as string) ?? "";
    const context = (taskData["context"] as Record<string, unknown>) ?? {};
    const interfaces = (context["interfaces"] as Array<Record<string, string>>) ?? [];

    this.log.info(`开始开发: ${title}`);

    try {
      const result = await this.develop(title, description, interfaces, language);
      const filepath = this.saveCode(result);

      await this.sendTaskResult(message, {
        title,
        filename: result.filename,
        filepath,
        language: result.language,
        code: result.code,
        description: result.description,
        dependencies: result.dependencies,
      });
      this.log.info(`开发完成: ${result.filename}`);
    } catch (err) {
      this.log.error(`代码生成失败: ${title} — ${String(err)}`);
      await this.sendError(message, String(err));
    }
  }

  private async handleReviewFeedback(message: Message): Promise<void> {
    const issues = (message.content["issues"] as Array<Record<string, unknown>>) ?? [];
    const code = (message.content["code"] as string) ?? "";
    const language = (message.content["language"] as string) ?? "typescript";

    this.log.info(`收到 ${issues.length} 条审核意见，开始修复...`);

    try {
      const fixedCode = await this.fixCode(code, issues, language);
      await this.sendTaskResult(message, { code: fixedCode, fixesApplied: issues.length, status: "fixed" });
    } catch (err) {
      await this.sendError(message, String(err));
    }
  }

  // ── 核心开发 ──────────────────────────────────

  async develop(
    title: string,
    description: string,
    interfaces: Array<Record<string, string>>,
    language = "typescript",
    useLLM = true
  ): Promise<DevelopResult> {
    if (useLLM) {
      try {
        return await this.llmDevelop(title, description, interfaces, language);
      } catch (err) {
        this.log.warn(`LLM 代码生成失败，使用模板: ${String(err)}`);
      }
    }
    return this.templateDevelop(title, description, interfaces, language);
  }

  private async llmDevelop(
    title: string,
    description: string,
    interfaces: Array<Record<string, string>>,
    language: string
  ): Promise<DevelopResult> {
    // RAG: 从项目知识库检索相关代码作为参考
    const ragContext = ragIndex.getContext(`${title} ${description}`, 3, 2000);

    const prompt = `请为以下开发任务生成代码：

## 任务标题
${title}

## 任务描述
${description}

## 接口规范
${JSON.stringify(interfaces, null, 2)}

## 目标语言
${language}

${ragContext}

请生成完整的、可直接运行的代码。`;

    const response = await this.llm.chatWithJSON(
      [{ role: "user", content: prompt }],
      { systemPrompt: DEVELOPER_SYSTEM_PROMPT, temperature: 0.5, maxTokens: 8192 }
    );

    let jsonStr = response.trim();
    jsonStr = jsonStr.replace(/^```(?:json)?\s*/i, "");
    jsonStr = jsonStr.replace(/\s*```$/i, "");
    const data = JSON.parse(jsonStr) as Record<string, unknown>;
    return {
      filename: (data["filename"] as string) ?? "output.ts",
      language: (data["language"] as string) ?? language,
      code: ((data["code"] as string) ?? "").replace(/\\n/g, "\n").replace(/\\t/g, "  "),
      description: (data["description"] as string) ?? description,
      dependencies: (data["dependencies"] as string[]) ?? [],
      entryPoint: data["entry_point"] as string | undefined,
    };
  }

  templateDevelop(
    title: string,
    description: string,
    interfaces: Array<Record<string, string>>,
    language: string
  ): DevelopResult {
    const lines: string[] = [];

    if (language === "typescript") {
      lines.push("/**");
      lines.push(` * ${title}`);
      lines.push(` * ${description}`);
      lines.push(" */");
      lines.push("");

      for (const iface of interfaces) {
        lines.push(...this.generateTSStub(iface));
        lines.push("");
      }

      if (interfaces.length === 0) {
        const className = this.titleToClass(title);
        lines.push(`export class ${className} {`);
        lines.push(`  /** ${description} */`);
        lines.push("  constructor() {}");
        lines.push("");
        lines.push("  execute(...args: unknown[]): unknown {");
        lines.push("    throw new Error('Not implemented');");
        lines.push("  }");
        lines.push("}");
      }

      lines.push("");
      lines.push("// Entry point");
      lines.push("if (import.meta.main) {");
      lines.push("  console.log('Running...');");
      lines.push("}");
    } else {
      // Python fallback
      lines.push('"""');
      lines.push(title);
      lines.push(description);
      lines.push('"""');
      lines.push("");

      for (const iface of interfaces) {
        lines.push(...this.generatePyStub(iface));
        lines.push("");
      }

      if (interfaces.length === 0) {
        const className = this.titleToClass(title);
        lines.push(`class ${className}:`);
        lines.push(`    """${description}"""`);
        lines.push("    def __init__(self):");
        lines.push("        pass");
      }
    }

    return {
      filename: this.titleToFilename(title, language),
      language,
      code: lines.join("\n"),
      description,
      dependencies: [],
    };
  }

  private generateTSStub(iface: Record<string, string>): string[] {
    const desc = iface["description"] ?? "";
    const inputDesc = iface["input"] ?? "";
    const outputDesc = iface["output"] ?? "";
    const funcName = this.pathToFuncName(iface["path"] ?? "handler");

    return [
      "/**",
      ` * ${desc}`,
      inputDesc ? ` * @param request - ${inputDesc}` : "",
      outputDesc ? ` * @returns ${outputDesc}` : "",
      " */",
      `export function ${funcName}(request: unknown): unknown {`,
      `  console.log('${funcName} called');`,
      "  // TODO: implement",
      "  throw new Error('Not implemented');",
      "}",
    ].filter(Boolean);
  }

  private generatePyStub(iface: Record<string, string>): string[] {
    const desc = iface["description"] ?? "";
    const funcName = this.pathToFuncName(iface["path"] ?? "handler");
    return [
      `def ${funcName}(request):`,
      `    """${desc}"""`,
      "    # TODO: implement",
      "    raise NotImplementedError",
    ];
  }

  // ── 代码修复 ──────────────────────────────────

  async fixCode(
    code: string,
    issues: Array<Record<string, unknown>>,
    language: string
  ): Promise<string> {
    try {
      const prompt = `请修复以下 ${language} 代码中的所有问题。

原始代码：
\`\`\`${language}
${code}
\`\`\`

发现的问题：
${JSON.stringify(issues, null, 2)}

返回 JSON: {"code": "完整的修复后代码"}`;

      const response = await this.llm.chatWithJSON(
        [{ role: "user", content: prompt }],
        { systemPrompt: "你是代码修复专家。根据问题列表修复代码。只返回 JSON。", temperature: 0.2 }
      );

      let jsonStr = response.trim();
      jsonStr = jsonStr.replace(/^```(?:json)?\s*/i, "");
      jsonStr = jsonStr.replace(/\s*```$/i, "");
      const data = JSON.parse(jsonStr) as { code: string };
      return (data["code"] ?? code).replace(/\\n/g, "\n").replace(/\\t/g, "  ");
    } catch {
      // Fallback: add FIXME comments
      const fixNotes = issues
        .map(
          (i) =>
            `// FIXME: [${i["severity"] ?? "info"}] ${i["title"] ?? ""} — ${i["suggestion"] ?? ""}`
        )
        .join("\n");
      return `${fixNotes}\n\n${code}`;
    }
  }

  // ── 文件保存 ──────────────────────────────────

  saveCode(result: DevelopResult): string {
    const filepath = resolve(this.outputDir, result.filename);
    try { mkdirSync(dirname(filepath), { recursive: true }); } catch {}
    writeFileSync(filepath, result.code, "utf-8");
    this.log.info(`代码已保存: ${filepath}`);
    return filepath;
  }

  // ── 工具方法 ──────────────────────────────────

  titleToFilename(title: string, language: string): string {
    const extMap: Record<string, string> = {
      typescript: ".ts", python: ".py", go: ".go", rust: ".rs",
    };
    const ext = extMap[language] ?? ".ts";
    const name = title
      .toLowerCase()
      .replace(/[^\w\s-]/g, "")
      .replace(/[-\s]+/g, "_");
    return `${name}${ext}`;
  }

  titleToClass(title: string): string {
    const name = title.replace(/[^\w\s-]/g, "");
    const words = name.split(/[-\s_]+/);
    return words.map((w) => w.charAt(0).toUpperCase() + w.slice(1)).join("") || "MainModule";
  }

  pathToFuncName(path: string): string {
    const name = path.includes("/") ? path.split("/").pop()! : path;
    return name.replace(/[^\w]/g, "_").replace(/_+/g, "_").replace(/^_|_$/g, "").toLowerCase() || "handler";
  }
}

/**
 * DocumenterAgent — 文档生成与项目复盘
 */

import { mkdirSync, writeFileSync } from "fs";
import { resolve, dirname } from "path";
import { BaseAgent } from "./base.js";
import { MessageBus } from "../message-bus.js";
import { LLMService, llmService } from "../services/llm.js";
import { AgentRole, Message, MessageType } from "../models/task.js";

const DOCUMENTER_SYSTEM_PROMPT = `你是一个资深技术文档工程师。根据项目的开发上下文生成专业的技术文档。

## 输出格式
返回 JSON：
{
  "title": "文档标题",
  "type": "api|readme|module|retrospective",
  "content": "完整的 Markdown 文档内容"
}`;

interface DocResult {
  title: string;
  type: string;
  content: string;
}

interface ProjectContext {
  name: string;
  description: string;
  modules: Array<{
    title: string;
    description: string;
    features: Array<{
      title: string;
      description: string;
      interfaces: Array<Record<string, string>>;
      steps: string[];
    }>;
  }>;
}

export class DocumenterAgent extends BaseAgent {
  readonly role: AgentRole = "documenter";
  private llm: LLMService;
  private outputDir: string;

  constructor(bus?: MessageBus, llm?: LLMService, outputDir = "./output/docs") {
    super(bus);
    this.llm = llm ?? llmService;
    this.outputDir = outputDir;
    mkdirSync(this.outputDir, { recursive: true });
  }

  async processMessage(message: Message): Promise<void> {
    if (message.msgType === "task_assign") {
      await this.handleDocTask(message);
    } else {
      await this.sendError(message, `未知消息类型: ${message.msgType}`);
    }
  }

  private async handleDocTask(message: Message): Promise<void> {
    const docType = (message.content["doc_type"] as string) ?? "readme";
    const projectContext = (message.content["project_context"] as ProjectContext) ?? {};
    const artifacts = (message.content["artifacts"] as Record<string, string>) ?? {};
    const interfaces = (message.content["interfaces"] as Array<Record<string, string>>) ?? [];
    const issues = (message.content["issues"] as Array<Record<string, unknown>>) ?? [];
    const useLLM = (message.content["use_llm"] as boolean) ?? true;

    this.log.info(`开始生成文档: ${docType}`);

    try {
      let doc: DocResult;
      switch (docType) {
        case "api":
          doc = await this.generateApiDoc(interfaces, artifacts, useLLM);
          break;
        case "module":
          doc = await this.generateModuleDoc(
            (message.content["module_name"] as string) ?? "未命名",
            (message.content["description"] as string) ?? "",
            artifacts,
            useLLM
          );
          break;
        case "retrospective":
          doc = await this.generateRetrospective(projectContext, artifacts, issues, useLLM);
          break;
        default:
          doc = await this.generateReadme(projectContext, artifacts, useLLM);
      }

      const filepath = this.saveDocument(doc);
      await this.sendTaskResult(message, { docType, title: doc.title, content: doc.content, filepath });
      this.log.info(`文档已生成: ${filepath}`);
    } catch (err) {
      this.log.error(`文档生成失败: ${String(err)}`);
      await this.sendError(message, String(err));
    }
  }

  // ── README ─────────────────────────────────────

  async generateReadme(
    projectContext: ProjectContext,
    artifacts: Record<string, string>,
    useLLM = true
  ): Promise<DocResult> {
    if (useLLM) {
      try {
        return await this.llmGenerate("readme", projectContext as unknown as Record<string, unknown>, {});
      } catch { /* fallback */ }
    }

    const name = projectContext.name ?? "未命名项目";
    const description = projectContext.description ?? "";
    const modules = projectContext.modules ?? [];

    const lines = [
      `# ${name}`,
      "",
      `> ${description}`,
      "",
      "## 📋 项目概述",
      "",
      description,
      "",
      "## 🏗️ 项目结构",
      "",
      "```",
      `${name}/`,
    ];

    for (const mod of modules) {
      lines.push(`├── ${mod.title}/`);
      for (const feat of mod.features) {
        lines.push(`│   ├── ${feat.title}`);
      }
    }

    lines.push("```", "", "## 🚀 快速开始", "", "```bash", "npm install", "npm run dev", "```", "");

    lines.push("## 📦 模块说明", "");
    for (const mod of modules) {
      lines.push(`### ${mod.title}`, mod.description, "");
    }

    lines.push("## 🔌 API 接口", "", "| 方法 | 路径 | 说明 |", "|------|------|------|");
    for (const mod of modules) {
      for (const feat of mod.features) {
        for (const iface of feat.interfaces) {
          lines.push(`| ${iface["method"] ?? "—"} | \`${iface["path"] ?? "—"}\` | ${iface["description"] ?? "—"} |`);
        }
      }
    }

    lines.push("", "## 🧪 测试", "", "```bash", "npm test", "```", "", "## 📄 许可证", "", "MIT");

    return { title: `${name} - README`, type: "readme", content: lines.join("\n") };
  }

  // ── API 文档 ───────────────────────────────────

  async generateApiDoc(
    interfaces: Array<Record<string, string>>,
    artifacts: Record<string, string>,
    useLLM = true
  ): Promise<DocResult> {
    if (useLLM) {
      try {
        return await this.llmGenerate("api", { interfaces, artifacts } as unknown as Record<string, unknown>, {});
      } catch { /* fallback */ }
    }

    const lines = [
      "# API 接口文档",
      "",
      `> 自动生成于 ${new Date().toISOString().slice(0, 19).replace("T", " ")}`,
      "",
      "## 接口列表",
      "",
    ];

    for (let i = 0; i < interfaces.length; i++) {
      const iface = interfaces[i]!;
      const method = iface["method"] ?? "GET";
      const path = iface["path"] ?? "/";
      const desc = iface["description"] ?? "";

      lines.push(`### ${i + 1}. ${method} \`${path}\``, "", `**说明**: ${desc}`, "");

      if (iface["input"]) {
        lines.push("**请求参数**:", "", "```json", iface["input"], "```", "");
      }
      if (iface["output"]) {
        lines.push("**响应格式**:", "", "```json", iface["output"], "```", "");
      }
      lines.push("---", "");
    }

    return { title: "API 接口文档", type: "api", content: lines.join("\n") };
  }

  // ── 模块文档 ───────────────────────────────────

  async generateModuleDoc(
    moduleName: string,
    description: string,
    artifacts: Record<string, string>,
    useLLM = true
  ): Promise<DocResult> {
    if (useLLM) {
      try {
        return await this.llmGenerate("module", { moduleName, description } as unknown as Record<string, unknown>, artifacts);
      } catch { /* fallback */ }
    }

    let codeSnippet = "";
    for (const [name, content] of Object.entries(artifacts)) {
      if (name.toLowerCase().includes(moduleName.toLowerCase())) {
        codeSnippet = content.slice(0, 500);
        break;
      }
    }

    const lines = [
      `# 模块: ${moduleName}`,
      "",
      `> ${description}`,
      "",
      "## 概述",
      "",
      description,
      "",
    ];

    if (codeSnippet) {
      lines.push("## 代码示例", "", "```typescript", codeSnippet, "```", "");
    }

    return { title: `模块文档 - ${moduleName}`, type: "module", content: lines.join("\n") };
  }

  // ── 复盘报告 ───────────────────────────────────

  async generateRetrospective(
    projectContext: ProjectContext,
    artifacts: Record<string, string>,
    issues: Array<Record<string, unknown>>,
    useLLM = true
  ): Promise<DocResult> {
    if (useLLM) {
      try {
        return await this.llmGenerate(
          "retrospective",
          { project: projectContext, artifacts, issues } as unknown as Record<string, unknown>,
          {}
        );
      } catch { /* fallback */ }
    }

    const name = projectContext.name ?? "未命名项目";
    const modules = projectContext.modules ?? [];
    const totalIssues = issues.length;
    const errorCount = issues.filter((i) => i["severity"] === "error").length;
    const warningCount = issues.filter((i) => i["severity"] === "warning").length;

    const lines = [
      `# 项目复盘报告: ${name}`,
      "",
      `> 生成于 ${new Date().toISOString().slice(0, 19).replace("T", " ")}`,
      "",
      "## 📊 项目概况",
      "",
      `- **项目名称**: ${name}`,
      `- **模块数量**: ${modules.length}`,
      `- **产出文件**: ${Object.keys(artifacts).length}`,
      `- **代码问题**: ${totalIssues} (${errorCount} 错误, ${warningCount} 警告)`,
      "",
      "## ✅ 完成情况",
      "",
    ];

    for (const mod of modules) {
      const totalSteps = mod.features.reduce((sum, f) => sum + f.steps.length, 0);
      lines.push(`- **${mod.title}**: ${mod.features.length} 功能, ${totalSteps} 步骤`);
    }

    lines.push("", "## 🐛 问题汇总", "");

    if (issues.length > 0) {
      lines.push("| 严重度 | 类别 | 说明 |", "|--------|------|------|");
      for (const issue of issues.slice(0, 20)) {
        lines.push(
          `| ${issue["severity"] ?? "—"} | ${issue["category"] ?? "—"} | ${issue["title"] ?? "—"} |`
        );
      }
    } else {
      lines.push("✅ 无遗留问题");
    }

    lines.push(
      "",
      "## 📝 经验总结",
      "",
      "### 做得好的",
      "- 需求拆解清晰，任务分配合理",
      "- 代码规范，类型标注完善",
      "",
      "### 需改进的",
      "- 初期应更多关注安全设计",
      "- 增加集成测试覆盖",
      "",
      "## 🎯 后续建议",
      "",
      "1. 补充端到端测试",
      "2. 添加 CI/CD 流水线",
      "3. 性能基准测试",
    );

    return { title: `项目复盘 - ${name}`, type: "retrospective", content: lines.join("\n") };
  }

  // ── LLM 辅助 ──────────────────────────────────

  private async llmGenerate(
    docType: string,
    context: Record<string, unknown>,
    artifacts: Record<string, string>
  ): Promise<DocResult> {
    const prompt = `请为以下项目生成 ${docType} 类型的 Markdown 文档。

## 项目上下文
${JSON.stringify(context, null, 2)}

## 代码产物
${JSON.stringify(
  Object.fromEntries(Object.entries(artifacts).map(([k, v]) => [k, v.slice(0, 200)])),
  null,
  2
)}`;

    const response = await this.llm.chatWithJSON(
      [{ role: "user", content: prompt }],
      { systemPrompt: DOCUMENTER_SYSTEM_PROMPT, temperature: 0.5, maxTokens: 4096 }
    );

    let jsonStr = response.trim();
    jsonStr = jsonStr.replace(/^```(?:json)?\s*/i, "");
    jsonStr = jsonStr.replace(/\s*```$/i, "");
    return JSON.parse(jsonStr) as DocResult;
  }

  // ── 保存 ──────────────────────────────────────

  saveDocument(doc: DocResult): string {
    const safeTitle = doc.title
      .toLowerCase()
      .replace(/[^\w\s-]/g, "")
      .replace(/\s+/g, "_")
      .slice(0, 50);
    const filename = `${doc.type}_${safeTitle}.md`;
    const filepath = resolve(this.outputDir, filename);
    try { mkdirSync(dirname(filepath), { recursive: true }); } catch {}
    writeFileSync(filepath, doc.content, "utf-8");
    this.log.info(`文档已保存: ${filepath}`);
    return filepath;
  }
}

/**
 * PlannerAgent — 需求分析与任务拆解
 */

import { BaseAgent } from "./base.js";
import { MessageBus } from "../message-bus.js";
import { LLMService, llmService } from "../services/llm.js";
import {
  AgentRole,
  Message,
  MessageType,
  Task,
  TaskPriority,
  createTask,
} from "../models/task.js";

const PLANNER_SYSTEM_PROMPT = `你是一个资深的软件架构师和项目经理。将用户的自然语言需求拆解为结构化的开发任务树。

## 输出格式
返回 JSON：
{
  "project_name": "项目名称",
  "summary": "一句话概述",
  "modules": [
    {
      "title": "模块名称",
      "description": "模块描述",
      "priority": "high|medium|low",
      "features": [
        {
          "title": "功能点",
          "description": "功能描述",
          "interfaces": [
            {"method": "GET|POST|PUT|DELETE|FUNC", "path": "/api/xxx 或 函数名", "description": "接口描述", "input": "输入", "output": "输出"}
          ],
          "steps": ["具体实现步骤1", "具体实现步骤2"]
        }
      ]
    }
  ],
  "dependencies": [{"task": "模块A.功能B", "depends_on": "模块X.功能Y", "reason": "原因"}]
}

## 拆解原则
1. 模块粒度适中 2. 功能点明确可独立交付 3. 接口清晰 4. 步骤可执行 5. 依赖合理
请直接返回 JSON，不要包含任何其他文字。`;

export class PlannerAgent extends BaseAgent {
  readonly role: AgentRole = "planner";
  private llm: LLMService;

  constructor(bus?: MessageBus, llm?: LLMService) {
    super(bus);
    this.llm = llm ?? llmService;
  }

  async processMessage(message: Message): Promise<void> {
    if (message.msgType === "task_assign") {
      await this.handlePlanRequest(message);
    } else if (message.msgType === "task_query") {
      await this.handleQuery(message);
    } else {
      await this.sendError(message, `未知消息类型: ${message.msgType}`);
    }
  }

  private async handlePlanRequest(message: Message): Promise<void> {
    const requirement = message.content["requirement"] as string;
    const useLLM = (message.content["use_llm"] as boolean) ?? true;

    if (!requirement) {
      await this.sendError(message, "缺少需求描述 (requirement)");
      return;
    }

    this.log.info(`开始分析需求: ${requirement.slice(0, 80)}...`);

    try {
      const taskTree = await this.decompose(requirement, useLLM);
      await this.sendTaskResult(message, {
        taskTree,
        summary: taskTree.description,
        totalTasks: flattenCount(taskTree),
        modules: taskTree.children.map((c) => c.title),
      });
      this.log.info(
        `需求拆解完成: ${taskTree.children.length} 个模块, ${flattenCount(taskTree)} 个任务节点`
      );
    } catch (err) {
      this.log.error(`需求拆解失败: ${String(err)}`);
      await this.sendError(message, String(err));
    }
  }

  private async handleQuery(message: Message): Promise<void> {
    const taskId = message.content["task_id"] as string;
    await this.sendTaskResult(message, { queryAck: taskId });
  }

  // ── 核心拆解逻辑 ──────────────────────────────

  async decompose(requirement: string, useLLM = true): Promise<Task> {
    if (useLLM && this.llm.totalCalls >= 0) {
      try {
        return await this.llmDecompose(requirement);
      } catch (err) {
        this.log.warn(`LLM 拆解失败，回退到规则拆解: ${String(err)}`);
      }
    }
    return this.ruleDecompose(requirement);
  }

  private async llmDecompose(requirement: string): Promise<Task> {
    const response = await this.llm.chatWithJSON(
      [{ role: "user", content: requirement }],
      { systemPrompt: PLANNER_SYSTEM_PROMPT, temperature: 0.3, maxTokens: 4096 }
    );

    let jsonStr = response.trim();
    jsonStr = jsonStr.replace(/^```(?:json)?\s*/i, "");
    jsonStr = jsonStr.replace(/\s*```$/i, "");
    const data = JSON.parse(jsonStr) as Record<string, unknown>;
    return this.buildTaskTree(data, requirement);
  }

  ruleDecompose(requirement: string): Task {
    const lower = requirement.toLowerCase();
    const hasAuth = /登录|认证|权限|用户|auth/.test(lower);
    const hasStorage = /存储|文件|上传|下载|数据库/.test(lower);

    const modules: Array<Record<string, unknown>> = [
      {
        title: "核心功能模块",
        description: "实现核心业务逻辑",
        priority: "high",
        features: [
          {
            title: "主功能实现",
            description: requirement.trim(),
            interfaces: [
              { method: "FUNC", path: "main", description: "核心入口", input: "", output: "" },
            ],
            steps: [
              "定义数据模型和类型",
              "实现核心业务逻辑",
              "添加输入验证和错误处理",
              "编写单元测试",
            ],
          },
        ],
      },
    ];

    if (hasAuth) {
      modules.push({
        title: "用户认证模块",
        description: "用户注册、登录、权限管理",
        priority: "high",
        features: [
          {
            title: "用户管理",
            description: "注册、登录、Token 管理",
            interfaces: [
              { method: "POST", path: "/api/auth/register", description: "用户注册" },
              { method: "POST", path: "/api/auth/login", description: "用户登录" },
            ],
            steps: ["定义用户数据模型", "实现密码哈希与验证", "实现 JWT Token 生成与验证", "添加认证中间件"],
          },
        ],
      });
    }

    if (hasStorage) {
      modules.push({
        title: "数据存储模块",
        description: "数据持久化和文件管理",
        priority: "medium",
        features: [
          {
            title: "数据层",
            description: "数据库连接和 ORM 配置",
            interfaces: [
              { method: "FUNC", path: "connectDB", description: "数据库连接" },
              { method: "FUNC", path: "migrate", description: "数据库迁移" },
            ],
            steps: ["配置数据库连接", "定义 ORM 模型", "创建迁移脚本", "实现 CRUD 操作"],
          },
        ],
      });
    }

    modules.push({
      title: "配置与工具模块",
      description: "项目配置、日志、错误处理",
      priority: "low",
      features: [
        {
          title: "基础设施",
          description: "配置管理、日志、异常处理",
          interfaces: [],
          steps: ["实现配置加载（环境变量/.env）", "配置日志系统", "实现全局异常处理", "添加健康检查端点"],
        },
      ],
    });

    const data = {
      project_name: this.extractProjectName(requirement),
      summary: requirement.trim(),
      modules,
      dependencies: [] as Array<Record<string, unknown>>,
    };
    return this.buildTaskTree(data, requirement);
  }

  // ── 任务树构建 ────────────────────────────────

  private buildTaskTree(data: Record<string, unknown>, requirement: string): Task {
    const root = createTask({
      title: (data["project_name"] as string) ?? "未命名项目",
      description: (data["summary"] as string) ?? requirement,
      role: "orchestrator" as AgentRole,
      priority: "critical" as TaskPriority,
    });

    const modules = (data["modules"] as Array<Record<string, unknown>>) ?? [];
    for (const modData of modules) {
      const modPriority = (modData["priority"] as TaskPriority) ?? "medium";
      const moduleTask = createTask({
        title: modData["title"] as string,
        description: (modData["description"] as string) ?? "",
        role: "developer",
        priority: modPriority,
        parentId: root.id,
      });

      const features = (modData["features"] as Array<Record<string, unknown>>) ?? [];
      for (const featData of features) {
        const featureTask = createTask({
          title: featData["title"] as string,
          description: (featData["description"] as string) ?? "",
          role: "developer",
          priority: modPriority,
          parentId: moduleTask.id,
          context: {
            interfaces: (featData["interfaces"] as Array<unknown>) ?? [],
            module: modData["title"] as string,
          },
        });

        const steps = (featData["steps"] as string[]) ?? [];
        for (let i = 0; i < steps.length; i++) {
          const stepTask = createTask({
            title: `Step ${i + 1}: ${(steps[i] ?? "").slice(0, 60)}`,
            description: steps[i] ?? "",
            role: "developer",
            priority: modPriority,
            parentId: featureTask.id,
          });
          featureTask.children.push(stepTask);
        }
        moduleTask.children.push(featureTask);
      }
      root.children.push(moduleTask);
    }

    return root;
  }

  extractProjectName(requirement: string): string {
    const m1 = requirement.match(/一个?['「](.+?)['」]/);
    if (m1) return m1[1]!.trim();
    const m2 = requirement.match(/一个(.+?)(?:系统|平台|工具|应用|项目|服务|模块)/);
    if (m2) return m2[1]!.trim();
    return requirement.slice(0, 30).trim();
  }

  getExecutableTasks(tree: Task): Task[] {
    return flattenAll(tree).filter(
      (t) => t.children.length === 0 && t.status === "pending"
    );
  }
}

function flattenCount(task: Task): number {
  let count = 1;
  for (const child of task.children) count += flattenCount(child);
  return count;
}

function flattenAll(task: Task): Task[] {
  const result: Task[] = [task];
  for (const child of task.children) result.push(...flattenAll(child));
  return result;
}

/**
 * TesterAgent — 代码审查、BUG 检测、安全扫描
 */

import { BaseAgent } from "./base.js";
import { MessageBus } from "../message-bus.js";
import { LLMService, llmService } from "../services/llm.js";
import { AgentRole, Message, MessageType } from "../models/task.js";

const TESTER_SYSTEM_PROMPT = `你是一个资深 QA 工程师。请审查以下代码，找出所有问题。

## 检查维度
1. 语法错误 2. 逻辑漏洞 3. 安全风险（注入、硬编码密钥、XSS） 4. 边界异常 5. 性能问题 6. 最佳实践

## 输出格式
返回 JSON：
{
  "summary": "整体评价",
  "score": 85,
  "issues": [
    {"severity": "error|warning|info", "category": "syntax|logic|security|boundary|performance|practice",
     "title": "简短标题", "line": 42, "description": "详细描述", "suggestion": "修复建议"}
  ],
  "passed": true
}
请直接返回 JSON。`;

interface ReviewIssue {
  severity: "error" | "warning" | "info";
  category: string;
  title: string;
  line: number;
  description: string;
  suggestion: string;
}

interface ReviewResult {
  summary: string;
  score: number;
  issues: ReviewIssue[];
  passed: boolean;
}

type PatternEntry = [RegExp, string, ReviewIssue["severity"]];

export class TesterAgent extends BaseAgent {
  readonly role: AgentRole = "tester";
  private llm: LLMService;

  // ── 安全检测模式 ──
  private static readonly SECURITY_PATTERNS: PatternEntry[] = [
    [/(?:password|passwd|secret|api_key|apiKey|token)\s*[:=]\s*['"]([^'"]+)['"]/gi, "硬编码密钥/密码", "error"],
    [/exec\s*\(|eval\s*\(/g, "动态执行风险（exec/eval）", "warning"],
    [/SELECT.*\+|INSERT.*\+|UPDATE.*\+|DELETE.*\+/gi, "SQL 注入风险（字符串拼接）", "error"],
    [/dangerouslySetInnerHTML/g, "XSS 风险（dangerouslySetInnerHTML）", "warning"],
    [/\.innerHTML\s*=/g, "XSS 风险（innerHTML 赋值）", "warning"],
    [/pickle\.(?:load|loads)\(/g, "反序列化风险（pickle）", "warning"],
  ];

  private static readonly PRACTICE_PATTERNS: PatternEntry[] = [
    [/catch\s*\(\s*\)/, "空 catch 块无错误处理", "warning"],
    [/catch\s*\([^)]*\)\s*\{\s*\}/, "静默吞掉异常（空 catch）", "warning"],
    [/\/\/\s*TODO/g, "存在 TODO 标记", "info"],
    [/console\.log\(/g, "使用 console.log 而非 logger，生产环境不推荐", "info"],
    [/while\s*\(\s*true\s*\)/g, "while(true) 无限循环，确认是否有退出条件", "info"],
    [/any\b/g, "使用 any 类型，建议明确类型", "warning"],
  ];

  constructor(bus?: MessageBus, llm?: LLMService) {
    super(bus);
    this.llm = llm ?? llmService;
  }

  async processMessage(message: Message): Promise<void> {
    if (message.msgType === "task_assign" || message.msgType === "review_request") {
      await this.handleTestTask(message);
    } else {
      await this.sendError(message, `未知消息类型: ${message.msgType}`);
    }
  }

  private async handleTestTask(message: Message): Promise<void> {
    const code = (message.content["code"] as string) ?? "";
    const language = (message.content["language"] as string) ?? "typescript";
    const useLLM = (message.content["use_llm"] as boolean) ?? true;

    if (!code) {
      await this.sendError(message, "缺少代码内容 (code)");
      return;
    }

    this.log.info(`开始代码审查: ${code.length} 字符`);
    const result = await this.review(code, language, useLLM);

    await this.sendTaskResult(message, {
      summary: result.summary,
      score: result.score,
      issues: result.issues,
      passed: result.passed,
      issueCount: result.issues.length,
    });

    this.log.info(
      `审查完成: 得分 ${result.score}, 问题 ${result.issues.length} 个, ${result.passed ? "✅ 通过" : "❌ 需修复"}`
    );
  }

  // ── 核心审查 ──────────────────────────────────

  async review(code: string, language = "typescript", useLLM = true): Promise<ReviewResult> {
    const staticIssues = this.staticAnalysis(code, language);

    let llmIssues: ReviewIssue[] = [];
    if (useLLM) {
      try {
        const llmResult = await this.llmReview(code, language);
        llmIssues = llmResult.issues ?? [];
      } catch (err) {
        this.log.warn(`LLM 审查失败，仅使用静态分析: ${String(err)}`);
      }
    }

    const allIssues = this.deduplicateIssues([...staticIssues, ...llmIssues]);
    const score = this.calculateScore(allIssues);
    const errorCount = allIssues.filter((i) => i.severity === "error").length;

    return {
      summary: this.generateSummary(allIssues, score),
      score,
      issues: allIssues,
      passed: errorCount === 0,
    };
  }

  private staticAnalysis(code: string, language: string): ReviewIssue[] {
    const issues: ReviewIssue[] = [];

    const allPatterns = [
      ...TesterAgent.SECURITY_PATTERNS,
      ...TesterAgent.PRACTICE_PATTERNS,
    ];

    for (const [pattern, desc, severity] of allPatterns) {
      const regex = new RegExp(pattern.source, pattern.flags);
      let match: RegExpExecArray | null;
      while ((match = regex.exec(code)) !== null) {
        const lineNo = code.slice(0, match.index).split("\n").length;
        issues.push({
          severity,
          category: "security",
          title: desc,
          line: lineNo,
          description: `发现潜在问题: ${desc}`,
          suggestion: "请按照最佳实践修复",
        });
        if (!pattern.flags.includes("g")) break;
      }
    }

    return issues;
  }

  private async llmReview(code: string, language: string): Promise<{ issues: ReviewIssue[]; score: number }> {
    const prompt = `请审查以下 ${language} 代码：

\`\`\`${language}
${code}
\`\`\`

请从语法、逻辑、安全、边界、性能、最佳实践六个维度进行全面审查。`;

    const response = await this.llm.chatWithJSON(
      [{ role: "user", content: prompt }],
      { systemPrompt: TESTER_SYSTEM_PROMPT, temperature: 0.3, maxTokens: 4096 }
    );

    let jsonStr = response.trim();
    jsonStr = jsonStr.replace(/^```(?:json)?\s*/i, "");
    jsonStr = jsonStr.replace(/\s*```$/i, "");
    return JSON.parse(jsonStr) as { issues: ReviewIssue[]; score: number };
  }

  private deduplicateIssues(issues: ReviewIssue[]): ReviewIssue[] {
    const seen = new Set<string>();
    const unique: ReviewIssue[] = [];
    for (const issue of issues) {
      const key = `${issue.line}:${issue.title}`;
      if (!seen.has(key)) {
        seen.add(key);
        unique.push(issue);
      }
    }
    const order = { error: 0, warning: 1, info: 2 } as const;
    return unique.sort((a, b) => order[a.severity] - order[b.severity] || a.line - b.line);
  }

  private calculateScore(issues: ReviewIssue[]): number {
    const deductions: Record<ReviewIssue["severity"], number> = {
      error: 15, warning: 5, info: 1,
    };
    let score = 100;
    for (const issue of issues) {
      score -= deductions[issue.severity];
    }
    return Math.max(0, Math.min(100, score));
  }

  private generateSummary(issues: ReviewIssue[], score: number): string {
    const errors = issues.filter((i) => i.severity === "error").length;
    const warnings = issues.filter((i) => i.severity === "warning").length;
    const infos = issues.filter((i) => i.severity === "info").length;

    const parts: string[] = [];
    if (errors) parts.push(`${errors} 个错误`);
    if (warnings) parts.push(`${warnings} 个警告`);
    if (infos) parts.push(`${infos} 个建议`);
    if (parts.length === 0) return `代码审查通过，得分 ${score}/100 ✅`;
    return `发现 ${parts.join(", ")}，得分 ${score}/100`;
  }

  formatReport(result: ReviewResult): string {
    const lines = [
      "=".repeat(60),
      "  代码审查报告",
      "=".repeat(60),
      `  评分: ${result.score}/100  ${result.passed ? "✅ 通过" : "❌ 需修复"}`,
      `  摘要: ${result.summary}`,
      "",
    ];

    if (result.issues.length > 0) {
      lines.push("  问题列表:");
      lines.push("  " + "-".repeat(56));
      for (let i = 0; i < result.issues.length; i++) {
        const issue = result.issues[i]!;
        const icon = { error: "🔴", warning: "🟡", info: "🔵" }[issue.severity] ?? "⚪";
        lines.push(
          `  ${i + 1}. ${icon} [${issue.severity.toUpperCase()}] L${issue.line}: ${issue.title}`
        );
        if (issue.suggestion) lines.push(`     建议: ${issue.suggestion}`);
        lines.push("");
      }
    }

    lines.push("=".repeat(60));
    return lines.join("\n");
  }
}

#!/usr/bin/env node
/**
 * MACA CLI — 多智能体协同开发助手命令行入口
 *
 *   maca run "开发一个XXX"
 *   maca demo
 *   maca plan "需求"
 *   maca review <file>
 */

import { Command } from "commander";
import chalk from "chalk";
import { readFileSync, mkdirSync, writeFileSync } from "fs";
import { resolve, relative, dirname } from "path";
import { tmpdir } from "os";
import { MessageBus } from "./message-bus.js";
import { PlannerAgent } from "./agents/planner.js";
import { DeveloperAgent } from "./agents/developer.js";
import { TesterAgent } from "./agents/tester.js";
import { DocumenterAgent } from "./agents/documenter.js";
import { Orchestrator } from "./orchestrator.js";
import { createTask, flattenTasks, isLeafTask } from "./models/task.js";

const program = new Command();

function printBanner(): void {
  console.log("");
  console.log(chalk.cyan.bold("  MACA — Multi-Agent Collaborative Architect"));
  console.log(chalk.dim("  多智能体协同开发助手系统 v0.1.0"));
  console.log("");
}

program.name("maca").description("多智能体协同开发助手系统").version("0.1.0");

// ── run ─────────────────────────────────────────

program
  .command("run [requirement]")
  .description("启动完整开发流水线")
  .option("--no-llm", "禁用 LLM 增强")
  .option("-o, --output <dir>", "输出目录", "./output")
  .action(async (requirement: string | undefined, opts: { llm: boolean; output: string }) => {
    printBanner();
    if (!requirement) {
      console.log("请输入项目需求:");
      return;
    }
    console.log(chalk.bold(`需求: ${requirement}\n`));

    const bus = new MessageBus();
    bus.start();

    const agents = [
      new PlannerAgent(bus),
      new DeveloperAgent(bus, undefined, opts.output),
      new TesterAgent(bus),
      new DocumenterAgent(bus, undefined, `${opts.output}/docs`),
    ];
    const orch = new Orchestrator(bus, opts.output);

    for (const agent of agents) await agent.start();
    await orch.start();
    console.log(chalk.green("✅ 所有 Agent 已就绪\n"));

    const result = await orch.runPipeline(requirement);

    if (result.status === "completed") {
      console.log("");
      console.log(chalk.green.bold("📊 流水线统计:"));
      console.log(`  总任务: ${result.stats.totalTasks}`);
      console.log(`  完成: ${result.stats.completedTasks}`);
      console.log(`  修复迭代: ${result.stats.fixIterations}`);
      if (result.stats.elapsedSeconds) {
        console.log(`  耗时: ${result.stats.elapsedSeconds.toFixed(1)}s`);
      }
      console.log(`\n${chalk.green(`📁 输出目录: ${opts.output}`)}`);
    } else {
      console.log(chalk.red(`\n❌ 流水线失败: ${result.documentation["reason"]}`));
    }

    for (const agent of agents) await agent.stop();
    await orch.stop();
    bus.shutdown();
  });

// ── demo ────────────────────────────────────────

program
  .command("demo")
  .description("运行端到端演示（规则模式，无需 LLM）")
  .action(async () => {
    printBanner();
    console.log(chalk.yellow.bold("🎬 启动端到端演示...\n"));

    const bus = new MessageBus();
    bus.start();

    const outputDir = resolve(tmpdir(), `maca_demo_${Date.now()}`);
    mkdirSync(outputDir, { recursive: true });

    const planner = new PlannerAgent(bus);
    const developer = new DeveloperAgent(bus, undefined, outputDir);
    const tester = new TesterAgent(bus);
    const documenter = new DocumenterAgent(bus, undefined, resolve(outputDir, "docs"));

    const agents = [planner, developer, tester, documenter];
    for (const agent of agents) await agent.start();

    console.log(chalk.green("✅ 4 个 Agent 已就绪:"));
    const names = ["planner", "developer", "tester", "documenter"];
    const icons = ["📋", "🔨", "🧪", "📝"];
    const descs = ["需求分析 & 任务拆解", "代码编写 & 实现", "代码审查 & BUG 检测", "文档生成 & 项目复盘"];
    for (let i = 0; i < agents.length; i++) {
      console.log(`  ${icons[i]} ${chalk.cyan(names[i])} — ${descs[i]}`);
    }

    // Step 1: Plan
    const requirement = "开发一个用户认证 API 服务，支持邮箱注册、JWT 登录、密码重置";
    console.log(chalk.cyan.bold("\n📋 Step 1: 需求拆解"));
    console.log(`  输入: ${requirement}`);

    const tree = planner.ruleDecompose(requirement);
    console.log(chalk.green(`  ✅ ${tree.children.length} 个模块`));
    for (const mod of tree.children) {
      const features = mod.children.length;
      const steps = mod.children.reduce((s, f) => s + f.children.length, 0);
      console.log(`    ├─ 📦 ${chalk.bold(mod.title)} (${features} 功能, ${steps} 步骤)`);
    }

    // Step 2: Develop
    const leaves = flattenTasks(tree).filter(isLeafTask);
    console.log(chalk.cyan.bold(`\n🔨 Step 2: 代码开发 (${Math.min(5, leaves.length)}/${leaves.length} 个任务)`));

    const artifacts: Record<string, string> = {};
    for (let i = 0; i < Math.min(5, leaves.length); i++) {
      const task = leaves[i]!;
      console.log(`  [${i + 1}] 🔨 ${task.title}...`);
      const result = developer.templateDevelop(
        task.title,
        task.description,
        (task.context["interfaces"] as Array<Record<string, string>>) ?? [],
        "typescript"
      );
      const fp = developer.saveCode(result);
      artifacts[task.id] = fp;
      console.log(`      ✅ ${relative(outputDir, fp)}`);
    }

    // Step 3: Test
    console.log(chalk.cyan.bold("\n🧪 Step 3: 代码审查"));
    let totalIssues = 0;
    for (const [taskId, filepath] of Object.entries(artifacts)) {
      const code = readFileSync(filepath, "utf-8");
      const review = await tester.review(code, "typescript", false);
      const icon = review.passed ? "✅" : "❌";
      console.log(`  ${icon} ${relative(outputDir, filepath)}: ${review.score}/100 (${review.issues.length} 问题)`);
      totalIssues += review.issues.length;
    }

    // Step 4: Document
    console.log(chalk.cyan.bold("\n📝 Step 4: 文档生成"));

    const projectCtx = {
      name: tree.title,
      description: tree.description,
      modules: tree.children.map((mod) => ({
        title: mod.title,
        description: mod.description,
        features: mod.children.map((feat) => ({
          title: feat.title,
          description: feat.description,
          interfaces: (feat.context["interfaces"] as Array<Record<string, string>>) ?? [],
          steps: feat.children.map((s) => s.title),
        })),
      })),
    };

    const readme = await documenter.generateReadme(projectCtx, artifacts, false);
    const readmePath = documenter.saveDocument(readme);
    console.log(`  ✅ README: ${relative(outputDir, readmePath)}`);

    const retro = await documenter.generateRetrospective(projectCtx, artifacts, [], false);
    const retroPath = documenter.saveDocument(retro);
    console.log(`  ✅ 复盘: ${relative(outputDir, retroPath)}`);

    // Summary
    console.log(chalk.green.bold(`\n${"=".repeat(50)}`));
    console.log(chalk.green.bold("  ✅ 演示完成!"));
    console.log(chalk.green.bold("=".repeat(50)));
    console.log(`  模块: ${tree.children.length} | 任务: ${leaves.length} | 代码: ${Object.keys(artifacts).length} | 问题: ${totalIssues}`);
    console.log(`  📁 ${outputDir}`);

    for (const agent of agents) await agent.stop();
    bus.shutdown();
  });

// ── plan ────────────────────────────────────────

program
  .command("plan <requirement>")
  .description("仅运行需求拆解")
  .option("--no-llm", "禁用 LLM")
  .action(async (requirement: string, opts: { llm: boolean }) => {
    printBanner();
    const bus = new MessageBus();
    bus.start();

    const planner = new PlannerAgent(bus);
    await planner.start();

    const tree = await planner.decompose(requirement, opts.llm);
    console.log(`\n${chalk.bold("项目:")} ${tree.title}`);
    console.log(`${chalk.bold("模块:")} ${tree.children.length}`);
    console.log(`${chalk.bold("总节点:")} ${flattenTasks(tree).length}\n`);

    function print(t: typeof tree, indent = 0): void {
      const prefix = "  ".repeat(indent) + (indent > 0 ? "├─ " : "");
      const icon = { pending: "⏳", in_progress: "🔄", completed: "✅", failed: "❌", blocked: "🔒", awaiting_review: "👁️" }[
        t.status
      ] ?? "❓";
      console.log(`${prefix}${icon} ${t.title}`);
      for (const child of t.children) print(child, indent + 1);
    }
    print(tree);

    await planner.stop();
    bus.shutdown();
  });

