/**
 * Mini LangGraph — 声明式 Agent 工作流引擎
 *
 * 核心理念：把 Agent 之间的跳转逻辑从代码里抽出来，变成可配置的图
 *
 * 三个概念：
 *   State  — 所有节点共享的数据
 *   Node   — 一个处理步骤，接收 State，返回部分新 State
 *   Edge   — 节点之间的连线（普通边 / 条件边）
 */

// ── 类型定义 ──────────────────────────────────

/** 任意 State 类型（用户自定义） */
type AnyState = Record<string, unknown>;

/** 一个节点：接收完整 State，返回要合并的部分 State */
type NodeFn<S extends AnyState> = (state: S) => Promise<Partial<S>>;

/** 条件判断：根据 State 决定下一步去哪 */
type RouterFn<S extends AnyState> = (state: S) => string;

/** 图的内部结构 */
interface GraphDef<S extends AnyState> {
  nodes: Map<string, NodeFn<S>>;
  edges: Map<string, string>;                    // from → to
  conditionalEdges: Map<string, RouterFn<S>>;    // from → router function
  entryPoint: string;
}

// ── Graph Builder ─────────────────────────────

class StateGraph<S extends AnyState> {
  private def: GraphDef<S> = {
    nodes: new Map(),
    edges: new Map(),
    conditionalEdges: new Map(),
    entryPoint: "",
  };

  /** 注册一个节点 */
  addNode(name: string, fn: NodeFn<S>): this {
    this.def.nodes.set(name, fn);
    if (!this.def.entryPoint) this.def.entryPoint = name;
    return this;
  }

  /** 普通边：A 执行完 → 直接去 B */
  addEdge(from: string, to: string): this {
    this.def.edges.set(from, to);
    return this;
  }

  /** 条件边：A 执行完 → 根据 router 函数的结果决定去 B、C 还是 D */
  addConditionalEdges(from: string, router: RouterFn<S>): this {
    this.def.conditionalEdges.set(from, router);
    return this;
  }

  /** 设置入口节点 */
  setEntryPoint(name: string): this {
    this.def.entryPoint = name;
    return this;
  }

  /** 编译成可执行的函数 */
  compile(): (initialState: S) => Promise<S> {
    const { nodes, edges, conditionalEdges, entryPoint } = this.def;

    return async (initialState: S): Promise<S> => {
      let state = { ...initialState };
      let currentNode = entryPoint;
      const visited = new Set<string>();
      const maxSteps = 50;

      for (let step = 0; step < maxSteps; step++) {
        if (!currentNode) break;

        // 防死循环
        if (visited.has(currentNode)) {
          console.warn(`[Graph] 检测到循环回到 ${currentNode}，继续执行`);
        }
        visited.add(currentNode);

        const nodeFn = nodes.get(currentNode);
        if (!nodeFn) throw new Error(`节点 "${currentNode}" 未注册`);

        // 执行节点，合并返回的 State
        console.log(`[Graph] 执行节点: ${currentNode}`);
        const partial = await nodeFn(state);
        state = { ...state, ...partial };

        // 决定下一个节点
        const condRouter = conditionalEdges.get(currentNode);
        if (condRouter) {
          // 条件边：根据 router 返回值决定
          currentNode = condRouter(state);
        } else {
          // 普通边
          currentNode = edges.get(currentNode) ?? "";
        }
      }

      return state;
    };
  }
}

// ── 导出 ──────────────────────────────────────

export { StateGraph };
export type { AnyState, NodeFn, RouterFn };

/**
 * 消息总线 — Agent 之间的异步通信中枢
 *
 * 基于 EventEmitter + Promise 实现：
 * - Agent 注册 / 注销
 * - 点对点消息发送（每个 Agent 独立的队列）
 * - 广播消息
 * - 请求-响应模式（sendAndWait）
 * - 消息审计日志
 */

import { EventEmitter } from "events";
import {
  AgentRole,
  Message,
  MessageType,
  createMessage,
} from "./models/task.js";
import { logger } from "./utils/logger.js";

export class MessageBus extends EventEmitter {
  /** 每个 Agent 角色的消息队列 */
  private queues = new Map<AgentRole, Message[]>();

  /** 消息历史 */
  private history: Message[] = [];

  /** 等待回复的 Promise resolver 映射 */
  private pendingReplies = new Map<string, (msg: Message) => void>();

  private running = false;

  // ── Agent 管理 ──────────────────────────────────

  register(role: AgentRole): void {
    if (!this.queues.has(role)) {
      this.queues.set(role, []);
    }
    logger.info(`[MessageBus] Agent 注册: ${role}`);
  }

  unregister(role: AgentRole): void {
    this.queues.delete(role);
    logger.info(`[MessageBus] Agent 注销: ${role}`);
  }

  get registeredAgents(): AgentRole[] {
    return [...this.queues.keys()];
  }

  // ── 发送 ───────────────────────────────────────

  send(message: Message): void {
    this.history.push(message);

    // 先 resolve pending reply — 即使接收者未注册也要 resolve
    this.resolvePendingReply(message);

    const queue = this.queues.get(message.receiver);
    if (!queue) {
      logger.warn(`[MessageBus] 接收者 ${message.receiver} 未注册，消息丢弃: ${message.id}`);
      return;
    }

    queue.push(message);
    this.emit("message", message);
    logger.debug(`[${message.sender}] → [${message.receiver}] ${message.msgType} (${message.id})`);
  }

  broadcast(message: Message, excludeSender = true): void {
    this.history.push(message);

    let sent = 0;
    for (const [role, queue] of this.queues) {
      if (excludeSender && role === message.sender) continue;
      queue.push(message);
      this.emit("message", message);
      sent++;
    }
    logger.debug(`[${message.sender}] → ALL(${sent}) broadcast (${message.id})`);
  }

  reply(original: Message, msgType: MessageType, content: Record<string, unknown>): Message {
    const replyMsg = createMessage({
      msgType,
      sender: original.receiver,
      receiver: original.sender,
      taskId: original.taskId,
      content,
      replyTo: original.id,
      correlationId: original.correlationId,
    });
    this.send(replyMsg);
    return replyMsg;
  }

  // ── 接收 ───────────────────────────────────────

  async receive(role: AgentRole, timeoutMs = 500): Promise<Message | null> {
    const queue = this.queues.get(role);
    if (!queue) return null;

    if (queue.length > 0) {
      return queue.shift()!;
    }

    // 等待新消息
    return new Promise<Message | null>((resolve) => {
      const timer = setTimeout(() => {
        cleanup();
        resolve(null);
      }, timeoutMs);

      const onMessage = (msg: Message) => {
        if (msg.receiver === role) {
          cleanup();
          resolve(msg);
        }
      };

      const cleanup = () => {
        clearTimeout(timer);
        this.off("message", onMessage);
      };

      this.on("message", onMessage);
    });
  }

  async receiveAll(role: AgentRole, timeoutMs = 500): Promise<Message[]> {
    const messages: Message[] = [];
    while (true) {
      const msg = await this.receive(role, timeoutMs);
      if (!msg) break;
      messages.push(msg);
    }
    return messages;
  }

  // ── 请求-响应 ──────────────────────────────────

  async sendAndWait(message: Message, timeoutMs = 60_000): Promise<Message | null> {
    if (!message.correlationId) {
      message.correlationId = message.id;
    }

    const corrId = message.correlationId;

    return new Promise<Message | null>((resolve) => {
      const timer = setTimeout(() => {
        this.pendingReplies.delete(corrId);
        logger.warn(`[MessageBus] 等待回复超时: correlation_id=${corrId}`);
        resolve(null);
      }, timeoutMs);

      this.pendingReplies.set(corrId, (msg: Message) => {
        clearTimeout(timer);
        resolve(msg);
      });

      this.send(message);
    });
  }

  private resolvePendingReply(message: Message): boolean {
    // 只有回复消息才触发 resolve
    if (!message.replyTo) return false;
    const corrId = message.correlationId;
    if (!corrId) return false;

    const resolver = this.pendingReplies.get(corrId);
    if (resolver) {
      this.pendingReplies.delete(corrId);
      resolver(message);
      return true;
    }
    return false;
  }

  // ── 查询 ───────────────────────────────────────

  getHistory(filter?: {
    sender?: AgentRole;
    receiver?: AgentRole;
    msgType?: MessageType;
    taskId?: string;
  }, limit = 100): Message[] {
    let results = this.history;
    if (filter?.sender) results = results.filter((m) => m.sender === filter.sender);
    if (filter?.receiver) results = results.filter((m) => m.receiver === filter.receiver);
    if (filter?.msgType) results = results.filter((m) => m.msgType === filter.msgType);
    if (filter?.taskId) results = results.filter((m) => m.taskId === filter.taskId);
    return results.slice(-limit);
  }

  getConversation(correlationId: string): Message[] {
    return this.history.filter((m) => m.correlationId === correlationId);
  }

  // ── 生命周期 ──────────────────────────────────

  start(): void {
    this.running = true;
    logger.info("[MessageBus] 消息总线已启动");
  }

  shutdown(): void {
    this.running = false;
    this.queues.clear();
    this.pendingReplies.clear();
    logger.info("[MessageBus] 消息总线已关闭");
  }

  get messageCount(): number {
    return this.history.length;
  }
}

/** 全局单例 */
