/**
 * Orchestrator — 总控调度器（系统核心）
 *
 * 三阶段流水线: PLAN → DEVELOP+TEST+FIX → DOCUMENT → DONE
 */

import { BaseAgent } from "./agents/base.js";
import { MessageBus } from "./message-bus.js";
import {
  AgentRole,
  Message,
  MessageType,
  Task,
  TaskStatus,
  createMessage,
  createTask,
  flattenTasks,
  isLeafTask,
} from "./models/task.js";
import { logger } from "./utils/logger.js";

type PipelinePhase = "idle" | "planning" | "developing" | "testing" | "fixing" | "documenting" | "done" | "failed";

interface PipelineResult {
  status: "completed" | "failed";
  projectName?: string;
  requirement?: string;
  stats: {
    totalTasks: number;
    completedTasks: number;
    failedTasks: number;
    fixIterations: number;
    startedAt: Date | null;
    completedAt: Date | null;
    elapsedSeconds?: number;
  };
  artifacts: Record<string, string>;
  reviewResults: Record<string, { score?: number; issues: number }>;
  documentation: Record<string, unknown>;
  outputDir: string;
}

export class Orchestrator extends BaseAgent {
  readonly role: AgentRole = "orchestrator";

  private TASK_TIMEOUT = 120_000; // ms
  private MAX_FIX_ITERATIONS = 3;
  private REVIEW_PASS_THRESHOLD = 80;

  private get useLLM(): boolean {
    return !process.env["MACA_TEST_MODE"];
  }

  private outputDir: string;
  private phase: PipelinePhase = "idle";
  private taskTree: Task | null = null;
  private artifacts: Record<string, string> = {};
  private reviewResults: Record<string, { score?: number; issues: number }> = {};
  private currentRequirement = "";

  private stats = {
    totalTasks: 0,
    completedTasks: 0,
    failedTasks: 0,
    fixIterations: 0,
    startedAt: null as Date | null,
    completedAt: null as Date | null,
  };

  constructor(bus?: MessageBus, outputDir = "./output") {
    super(bus);
    this.outputDir = outputDir;
    // Adjust timeouts for tests
    if (process.env["MACA_TEST_MODE"]) {
      this.TASK_TIMEOUT = 5000;
    }
  }

  // ═══════════════════════════════════════════════
  // 消息处理
  // ═══════════════════════════════════════════════

  async processMessage(message: Message): Promise<void> {
    if (message.msgType === "task_assign") {
      const requirement = message.content["requirement"] as string;
      if (requirement) {
        // Fire and forget — pipeline runs async
        this.runPipeline(requirement).then((result) => {
          this.sendTaskResult(message, result as unknown as Record<string, unknown>);
        });
      } else {
        await this.sendError(message, "缺少需求描述");
      }
    } else if (message.msgType === "task_result") {
      logger.debug(`收到异步结果: ${message.sender}`);
    } else if (message.msgType === "error") {
      logger.error(`[${message.sender}] 错误: ${String(message.content["error"])}`);
    }
  }

  // ═══════════════════════════════════════════════
  // 主流水线
  // ═══════════════════════════════════════════════

  async runPipeline(requirement: string): Promise<PipelineResult> {
    this.currentRequirement = requirement;
    this.stats.startedAt = new Date();
    this.phase = "planning";

    logger.phase("🚀 启动流水线");
    logger.info(`需求: ${requirement.slice(0, 100)}...`);

    try {
      // Phase 1: Plan
      const taskTree = await this.phasePlan(requirement);
      if (!taskTree) return this.fail("规划阶段失败");

      // Phase 2: Develop + Test
      await this.phaseDevelopAndTest(taskTree);

      // Phase 3: Document
      const docs = await this.phaseDocument(taskTree);

      this.phase = "done";
      this.stats.completedAt = new Date();

      const elapsed = this.stats.startedAt
        ? (this.stats.completedAt.getTime() - this.stats.startedAt.getTime()) / 1000
        : undefined;

      const result: PipelineResult = {
        status: "completed",
        projectName: this.taskTree?.title,
        requirement: this.currentRequirement,
        stats: { ...this.stats, elapsedSeconds: elapsed },
        artifacts: this.artifacts,
        reviewResults: this.reviewResults,
        documentation: docs,
        outputDir: this.outputDir,
      };

      logger.phase("✅ 流水线完成");
      logger.info(`统计: ${JSON.stringify(this.stats)}`);
      return result;
    } catch (err) {
      return this.fail(String(err));
    }
  }

  // ── Phase 1: Plan ─────────────────────────────

  private async phasePlan(requirement: string): Promise<Task | null> {
    logger.phase("📋 Phase 1/3: 需求分析与任务拆解");
    this.phase = "planning";

    const request = createMessage({
      msgType: "task_assign",
      sender: "orchestrator",
      receiver: "planner",
      content: { requirement, use_llm: this.useLLM },
    });

    const reply = await this.bus.sendAndWait(request, this.TASK_TIMEOUT);
    if (!reply || reply.msgType === "error") {
      logger.error("Planner 无响应或返回错误");
      return null;
    }

    const result = reply.content["result"] as Record<string, unknown> | undefined;
    const taskTree = result?.["taskTree"] as Task | undefined;
    if (!taskTree) {
      logger.error("Planner 返回空任务树");
      return null;
    }

    this.taskTree = taskTree;
    this.stats.totalTasks = flattenTasks(taskTree).length;
    logger.info(`任务树: ${taskTree.children.length} 个模块, ${this.stats.totalTasks} 个节点`);
    return taskTree;
  }

  // ── Phase 2: Develop + Test ──────────────────

  private async phaseDevelopAndTest(tree: Task): Promise<void> {
    logger.phase("🔨 Phase 2/3: 开发 & 测试");
    this.phase = "developing";

    const leaves = flattenTasks(tree).filter(isLeafTask);
    logger.info(`共 ${leaves.length} 个可执行任务`);

    for (let i = 0; i < leaves.length; i++) {
      const task = leaves[i]!;
      logger.info(`\n--- 任务 [${i + 1}/${leaves.length}]: ${task.title} ---`);

      task.status = "in_progress";
      task.startedAt = new Date();

      // Step A: Develop
      const codeResult = await this.dispatchDevelop(task);
      if (!codeResult) {
        task.status = "failed";
        this.stats.failedTasks++;
        continue;
      }

      const filepath = (codeResult["filepath"] as string) ?? "";
      this.artifacts[task.id] = filepath;
      const code = (codeResult["code"] as string) ?? "";

      // Step B: Test + Fix loop
      const passed = await this.testAndFixLoop(task, code);
      if (passed) {
        task.status = "completed";
        task.completedAt = new Date();
        this.stats.completedTasks++;
        logger.info(`✅ ${task.title} — 完成`);
      } else {
        task.status = "failed";
        this.stats.failedTasks++;
        logger.warn(`⚠️ ${task.title} — 审查未通过`);
      }
    }

    logger.info(`\n开发阶段完成: ${this.stats.completedTasks}/${leaves.length} 通过`);
  }

  async dispatchDevelop(task: Task): Promise<Record<string, unknown> | null> {
    this.phase = "developing";

    const request = createMessage({
      msgType: "task_assign",
      sender: "orchestrator",
      receiver: "developer",
      content: {
        task: {
          title: task.title,
          description: task.description,
          context: task.context,
        },
        language: (task.context["language"] as string) ?? "typescript",
        use_llm: this.useLLM,
      },
    });

    const reply = await this.bus.sendAndWait(request, this.TASK_TIMEOUT);
    if (!reply || reply.msgType === "error") {
      logger.error(`Developer 无响应: ${task.title}`);
      return null;
    }

    return reply.content["result"] as Record<string, unknown> | null;
  }

  async testAndFixLoop(task: Task, code: string): Promise<boolean> {
    for (let iter = 0; iter <= this.MAX_FIX_ITERATIONS; iter++) {
      this.phase = "testing";

      const review = await this.dispatchTest(code);
      if (!review) return false;

      this.reviewResults[task.id] = {
        score: review["score"] as number,
        issues: (review["issues"] as Array<unknown>)?.length ?? 0,
      };

      const score = (review["score"] as number) ?? 0;
      const issues = (review["issues"] as Array<Record<string, unknown>>) ?? [];
      const errors = issues.filter((i) => i["severity"] === "error");

      logger.info(`  审查 #${iter}: 得分 ${score}/100, ${errors.length} 错误`);

      if (score >= this.REVIEW_PASS_THRESHOLD && errors.length === 0) {
        return true;
      }

      if (iter >= this.MAX_FIX_ITERATIONS) break;

      this.phase = "fixing";
      this.stats.fixIterations++;
      logger.info(`  🔧 修复迭代 ${iter + 1}/${this.MAX_FIX_ITERATIONS}...`);

      const fixedCode = await this.dispatchFix(code, issues);
      if (!fixedCode) return false;
      code = fixedCode;
    }

    return false;
  }

  async dispatchTest(code: string): Promise<Record<string, unknown> | null> {
    const request = createMessage({
      msgType: "task_assign",
      sender: "orchestrator",
      receiver: "tester",
      content: { code, language: "typescript", use_llm: this.useLLM },
    });

    const reply = await this.bus.sendAndWait(request, this.TASK_TIMEOUT);
    if (!reply || reply.msgType === "error") {
      logger.error("Tester 无响应");
      return null;
    }

    return reply.content["result"] as Record<string, unknown> | null;
  }

  async dispatchFix(code: string, issues: Array<Record<string, unknown>>): Promise<string | null> {
    const request = createMessage({
      msgType: "review_response",
      sender: "orchestrator",
      receiver: "developer",
      content: { code, issues, language: "typescript" },
    });

    const reply = await this.bus.sendAndWait(request, this.TASK_TIMEOUT);
    if (!reply || reply.msgType === "error") {
      logger.error("Developer 修复失败");
      return null;
    }

    const result = reply.content["result"] as Record<string, unknown> | null;
    return (result?.["code"] as string) ?? null;
  }

  // ── Phase 3: Document ────────────────────────

  async phaseDocument(tree: Task): Promise<Record<string, unknown>> {
    logger.phase("📝 Phase 3/3: 文档生成");
    this.phase = "documenting";

    const projectContext = {
      name: tree.title,
      description: tree.description,
      modules: tree.children.map((mod) => ({
        title: mod.title,
        description: mod.description,
        features: mod.children.map((feat) => ({
          title: feat.title,
          description: feat.description,
          interfaces: (feat.context["interfaces"] as Array<Record<string, string>>) ?? [],
          steps: feat.children.map((s) => s.title),
        })),
      })),
    };

    const allInterfaces: Array<Record<string, string>> = [];
    for (const node of flattenTasks(tree)) {
      const ifaces = node.context["interfaces"] as Array<Record<string, string>> | undefined;
      if (ifaces) allInterfaces.push(...ifaces);
    }

    const allIssues: Array<Record<string, unknown>> = [];

    const request = createMessage({
      msgType: "task_assign",
      sender: "orchestrator",
      receiver: "documenter",
      content: {
        doc_type: "readme",
        project_context: projectContext,
        artifacts: this.artifacts,
        interfaces: allInterfaces,
        issues: allIssues,
        use_llm: this.useLLM,
      },
    });

    const reply = await this.bus.sendAndWait(request, this.TASK_TIMEOUT);
    if (!reply || reply.msgType === "error") {
      logger.error("Documenter 无响应");
      return {};
    }

    return (reply.content["result"] as Record<string, unknown>) ?? {};
  }

  // ── 结果 ─────────────────────────────────────

  private fail(reason: string): PipelineResult {
    this.phase = "failed";
    logger.error(`流水线失败: ${reason}`);
    return {
      status: "failed",
      stats: this.stats,
      artifacts: this.artifacts,
      reviewResults: this.reviewResults,
      documentation: { reason },
      outputDir: this.outputDir,
    };
  }
}

/**
 * 检查点管理器 — 断点续跑
 *
 * 每个任务完成后自动保存状态，系统崩溃后可以从上次中断的地方继续。
 */

import { mkdirSync, existsSync, readFileSync, writeFileSync } from "fs";
import { resolve } from "path";
import type { Task } from "../models/task.js";

export interface Checkpoint {
  projectId: string;
  requirement: string;
  taskTree: Task;
  completedTaskIds: string[];
  failedTaskIds: string[];
  currentTaskIndex: number;
  artifacts: Record<string, string>;
  reviewResults: Record<string, { score: number; issues: number }>;
  timestamp: number;
  version: number;
}

export class CheckpointManager {
  private dir: string;

  constructor(dir = ".maca") {
    this.dir = dir;
    mkdirSync(dir, { recursive: true });
  }

  /** 保存检查点 */
  save(checkpoint: Checkpoint): void {
    const path = resolve(this.dir, `${checkpoint.projectId}.json`);
    checkpoint.timestamp = Date.now();
    checkpoint.version = (checkpoint.version ?? 0) + 1;
    writeFileSync(path, JSON.stringify(checkpoint, null, 2), "utf-8");
  }

  /** 加载检查点 */
  load(projectId: string): Checkpoint | null {
    const path = resolve(this.dir, `${projectId}.json`);
    if (!existsSync(path)) return null;
    try {
      return JSON.parse(readFileSync(path, "utf-8")) as Checkpoint;
    } catch {
      return null;
    }
  }

  /** 列出所有保存的检查点 */
  list(): { projectId: string; timestamp: number; completed: number; total: number }[] {
    const { readdirSync } = require("fs");
    const files = readdirSync(this.dir).filter((f: string) => f.endsWith(".json"));
    return files.map((f: string) => {
      const c = JSON.parse(readFileSync(resolve(this.dir, f), "utf-8")) as Checkpoint;
      return {
        projectId: c.projectId,
        timestamp: c.timestamp,
        completed: c.completedTaskIds.length,
        total: flattenAll(c.taskTree).filter((t) => t.children.length === 0).length,
      };
    });
  }

  /** 删除检查点 */
  delete(projectId: string): void {
    const { unlinkSync } = require("fs");
    const path = resolve(this.dir, `${projectId}.json`);
    if (existsSync(path)) unlinkSync(path);
  }
}

function flattenAll(task: Task): Task[] {
  const r = [task];
  for (const c of task.children) r.push(...flattenAll(c));
  return r;
}

/**
 * LLM 服务 — OpenAI 兼容接口封装
 */

import OpenAI from "openai";
import { config } from "../utils/config.js";
import { logger } from "../utils/logger.js";

export interface LLMStats {
  totalCalls: number;
  totalTokens: number;
  totalTimeMs: number;
  avgTimeMs: number;
}

export class LLMService {
  private client: OpenAI;
  readonly model: string;

  totalCalls = 0;
  totalTokens = 0;
  totalTimeMs = 0;

  constructor(apiKey?: string, baseUrl?: string, model?: string) {
    this.model = model ?? config.openaiModel;
    this.client = new OpenAI({
      apiKey: apiKey ?? config.openaiApiKey,
      baseURL: baseUrl ?? config.openaiBaseUrl,
      timeout: config.llmTimeout * 1000,
      maxRetries: 0, // we handle retries ourselves
    });
  }

  // ── 核心调用 ──────────────────────────────────

  async chat(
    messages: OpenAI.Chat.Completions.ChatCompletionMessageParam[],
    opts?: {
      model?: string;
      temperature?: number;
      maxTokens?: number;
      systemPrompt?: string;
      maxRetries?: number;
    }
  ): Promise<string> {
    const {
      model,
      temperature = 0.7,
      maxTokens = 4096,
      systemPrompt,
      maxRetries = 3,
    } = opts ?? {};

    // Fail fast if no API key configured
    if (!this.client.apiKey) {
      throw new Error("No API key configured — skipping LLM call");
    }

    const fullMessages = systemPrompt
      ? [{ role: "system" as const, content: systemPrompt }, ...messages]
      : messages;

    let lastError: unknown;
    for (let attempt = 0; attempt < maxRetries; attempt++) {
      try {
        const start = performance.now();
        const response = await this.client.chat.completions.create({
          model: model ?? this.model,
          messages: fullMessages,
          temperature,
          max_tokens: maxTokens,
        });

        const elapsed = performance.now() - start;
        this.totalCalls++;
        this.totalTokens += response.usage?.total_tokens ?? 0;
        this.totalTimeMs += elapsed;

        logger.debug(
          `LLM 调用完成: model=${model ?? this.model}, ` +
            `tokens=${response.usage?.total_tokens ?? "?"}, ` +
            `time=${elapsed.toFixed(0)}ms`
        );

        return response.choices[0]?.message?.content ?? "";
      } catch (err) {
        lastError = err;
        if (attempt < maxRetries - 1) {
          const wait = 2 ** attempt;
          logger.warn(
            `LLM 调用失败 (attempt ${attempt + 1}/${maxRetries}): ${String(err)}. 等待 ${wait}s 后重试...`
          );
          await sleep(wait * 1000);
        }
      }
    }

    throw new Error(`LLM 调用失败（已重试 ${maxRetries} 次）: ${String(lastError)}`);
  }

  async chatWithJSON(
    messages: OpenAI.Chat.Completions.ChatCompletionMessageParam[],
    opts?: {
      model?: string;
      systemPrompt?: string;
      temperature?: number;
      maxTokens?: number;
    }
  ): Promise<string> {
    const jsonInstruction =
      "You MUST respond with valid JSON only. " +
      "No markdown fences, no explanations, just the JSON object.";

    const systemPrompt = opts?.systemPrompt
      ? `${opts.systemPrompt}\n\n${jsonInstruction}`
      : jsonInstruction;

    return this.chat(messages, {
      ...opts,
      systemPrompt,
      temperature: opts?.temperature ?? 0.3,
    });
  }

  async simplePrompt(
    prompt: string,
    opts?: { systemPrompt?: string; model?: string; temperature?: number }
  ): Promise<string> {
    return this.chat([{ role: "user", content: prompt }], opts);
  }

  // ── 统计 ──────────────────────────────────────

  get stats(): LLMStats {
    return {
      totalCalls: this.totalCalls,
      totalTokens: this.totalTokens,
      totalTimeMs: this.totalTimeMs,
      avgTimeMs: this.totalCalls > 0 ? this.totalTimeMs / this.totalCalls : 0,
    };
  }

  resetStats(): void {
    this.totalCalls = 0;
    this.totalTokens = 0;
    this.totalTimeMs = 0;
  }
}

function sleep(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

export const llmService = new LLMService();

/**
 * 流式进度推送 + 人工审核门禁
 */

import { EventEmitter } from "events";

// ── 进度事件 ──────────────────────────────────

export interface ProgressEvent {
  phase: string;
  message: string;
  percent: number;
  timestamp: number;
}

export class ProgressEmitter extends EventEmitter {
  private static instance: ProgressEmitter;
  static getInstance(): ProgressEmitter {
    if (!this.instance) this.instance = new ProgressEmitter();
    return this.instance;
  }

  emitProgress(phase: string, message: string, percent: number): void {
    this.emit("progress", {
      phase, message, percent,
      timestamp: Date.now(),
    } as ProgressEvent);
  }

  onProgress(handler: (event: ProgressEvent) => void): void {
    this.on("progress", handler);
  }
}

// ── 审核门禁 ──────────────────────────────────

export type ApprovalDecision = "approve" | "reject" | "skip";

export interface ApprovalRequest {
  id: string;
  title: string;
  description: string;
  severity: "critical" | "warning" | "info";
  context: Record<string, unknown>;
}

export class ApprovalGate {
  private pending: Map<string, {
    request: ApprovalRequest;
    resolve: (decision: ApprovalDecision) => void;
  }> = new Map();

  /** 提交审批请求，返回 Promise 等待人工决策 */
  async requestApproval(request: ApprovalRequest, timeoutMs = 120_000): Promise<ApprovalDecision> {
    return new Promise<ApprovalDecision>((resolve) => {
      const timer = setTimeout(() => {
        this.pending.delete(request.id);
        resolve("skip"); // 超时自动跳过
      }, timeoutMs);

      this.pending.set(request.id, {
        request,
        resolve: (decision) => {
          clearTimeout(timer);
          resolve(decision);
        },
      });
      // 可以通过 WebSocket/SSE 通知前端
    });
  }

  /** 人工做出决策 */
  decide(requestId: string, decision: ApprovalDecision): boolean {
    const entry = this.pending.get(requestId);
    if (!entry) return false;
    this.pending.delete(requestId);
    entry.resolve(decision);
    return true;
  }

  /** 获取所有待审批项 */
  getPending(): ApprovalRequest[] {
    return [...this.pending.values()].map((v) => v.request);
  }
}

// ── 安全检查器 ────────────────────────────────

export function shouldRequestApproval(issues: Array<{ severity: string; category: string }>): ApprovalRequest[] {
  return issues
    .filter((i) => i.severity === "error" && ["security", "logic"].includes(i.category))
    .map((i, idx) => ({
      id: `approval-${Date.now()}-${idx}`,
      title: i.severity === "error" ? `安全风险: ${i.category}` : `警告: ${i.category}`,
      description: `${i.category} 级别问题需要人工确认`,
      severity: (i.severity === "error" ? "critical" : "warning") as ApprovalRequest["severity"],
      context: { issue: i },
    }));
}

/**
 * RAG 检索增强模块
 *
 * 核心功能：Agent 做决策前，先从知识库检索相关上下文，注入到 Prompt 里
 *
 * 两种检索模式：
 *   1. 关键词检索（BM25 风格，零依赖）
 *   2. 向量检索（需 OpenAI/DeepSeek embedding API）
 *
 * 知识源：
 *   - 项目已有代码文件
 *   - 技术文档
 *   - 历史任务记录
 */

import { readFileSync, readdirSync, existsSync, statSync, writeFileSync, mkdirSync } from "fs";
import { resolve, relative, extname } from "path";
import { config } from "../utils/config.js";

// ── 文档块 ────────────────────────────────────

export interface Document {
  id: string;
  content: string;
  metadata: {
    source: string;       // 来源文件路径
    type: string;         // code / doc / log
    language?: string;
    timestamp: number;
  };
  embedding?: number[];
}

// ── 索引 ──────────────────────────────────────

export class RAGIndex {
  private documents: Document[] = [];
  private keywordIndex = new Map<string, Set<number>>();  // 词 → 文档索引集合
  private indexPath: string;

  constructor(indexPath = ".maca/rag_index.json") {
    this.indexPath = indexPath;
    this.load();
  }

  // ── 文档管理 ────────────────────────────────

  /** 添加文档 */
  add(doc: Document): void {
    const idx = this.documents.length;
    this.documents.push(doc);
    this.indexDocument(idx, doc.content);
  }

  /** 从目录批量索引 */
  indexDirectory(dirPath: string, extensions = [".ts", ".tsx", ".js", ".py", ".md"]): number {
    if (!existsSync(dirPath)) return 0;
    let count = 0;

    const walk = (path: string) => {
      const entries = readdirSync(path, { withFileTypes: true });
      for (const entry of entries) {
        const fullPath = resolve(path, entry.name);
        if (entry.isDirectory()) {
          if (!["node_modules", ".git", "dist", ".maca"].includes(entry.name)) {
            walk(fullPath);
          }
        } else if (extensions.includes(extname(entry.name))) {
          try {
            const content = readFileSync(fullPath, "utf-8");
            if (content.length > 0 && content.length < 100_000) {
              this.add({
                id: `doc-${count}`,
                content,
                metadata: {
                  source: relative(process.cwd(), fullPath),
                  type: extname(entry.name) === ".md" ? "doc" : "code",
                  language: extname(entry.name).slice(1),
                  timestamp: statSync(fullPath).mtimeMs,
                },
              });
              count++;
            }
          } catch { /* skip unreadable files */ }
        }
      }
    };

    walk(dirPath);
    this.save();
    return count;
  }

  // ── 检索 ────────────────────────────────────

  /** 关键词检索（BM25 简化版） */
  search(query: string, topK = 5): Document[] {
    const queryTerms = this.tokenize(query);
    if (queryTerms.length === 0) return [];

    const scores: Array<{ idx: number; score: number }> = [];

    for (let i = 0; i < this.documents.length; i++) {
      const doc = this.documents[i]!;
      const docTerms = this.tokenize(doc.content);

      // 计算 TF-IDF 简化分数
      let score = 0;
      const docTermSet = new Set(docTerms);

      for (const term of queryTerms) {
        if (docTermSet.has(term)) {
          const tf = docTerms.filter((t) => t === term).length / Math.max(docTerms.length, 1);
          const df = this.keywordIndex.get(term)?.size ?? 1;
          const idf = Math.log((this.documents.length + 1) / (df + 1));
          score += tf * idf;
        }
      }

      // 标题匹配加分
      if (doc.metadata.source.toLowerCase().includes(query.toLowerCase())) {
        score += 2;
      }

      if (score > 0) scores.push({ idx: i, score });
    }

    return scores
      .sort((a, b) => b.score - a.score)
      .slice(0, topK)
      .map((s) => this.documents[s.idx]!);
  }

  /** 获取检索结果的上下文文本（可直接注入 Prompt） */
  getContext(query: string, topK = 3, maxChars = 3000): string {
    const docs = this.search(query, topK);
    if (docs.length === 0) return "";

    const parts = ["## 项目已有相关代码（从知识库检索）\n"];
    for (const doc of docs) {
      const preview = doc.content.slice(0, maxChars / topK);
      parts.push(`### ${doc.metadata.source} (${doc.metadata.type})`);
      parts.push("```" + (doc.metadata.language ?? "") + "\n" + preview + "\n```\n");
    }
    return parts.join("\n");
  }

  // ── 向量检索（需 API） ──────────────────────

  /** 使用 DeepSeek Embedding 做语义检索 */
  async semanticSearch(query: string, topK = 5): Promise<Document[]> {
    if (!config.openaiApiKey) return this.search(query, topK); // 降级到关键词

    try {
      const { default: OpenAI } = await import("openai");
      const client = new OpenAI({
        apiKey: config.openaiApiKey,
        baseURL: config.openaiBaseUrl,
      });

      // 获取 query embedding
      const qResp = await client.embeddings.create({
        model: "text-embedding-3-small",
        input: query,
      });
      const queryVec = qResp.data[0]?.embedding;
      if (!queryVec) throw new Error("Embedding failed");

      // 计算余弦相似度
      const scores = this.documents.map((doc, idx) => {
        if (!doc.embedding) return { idx, score: 0 };
        return { idx, score: cosineSimilarity(queryVec, doc.embedding) };
      });

      return scores
        .sort((a, b) => b.score - a.score)
        .slice(0, topK)
        .map((s) => this.documents[s.idx]!);
    } catch {
      return this.search(query, topK);
    }
  }

  // ── 持久化 ──────────────────────────────────

  private save(): void {
    try {
      mkdirSync(".maca", { recursive: true });
      writeFileSync(this.indexPath, JSON.stringify({
        documents: this.documents.map((d) => ({
          ...d,
          embedding: undefined, // embedding 太大，不持久化
        })),
      }, null, 2), "utf-8");
    } catch { /* ignore */ }
  }

  private load(): void {
    try {
      if (existsSync(this.indexPath)) {
        const data = JSON.parse(readFileSync(this.indexPath, "utf-8"));
        this.documents = (data.documents ?? []).map((d: Document) => {
          if (d.content?.length > 0) {
            this.indexDocument(this.documents.length, d.content);
          }
          return d;
        });
      }
    } catch { /* ignore */ }
  }

  // ── 分词 ────────────────────────────────────

  private tokenize(text: string): string[] {
    return text
      .toLowerCase()
      .replace(/[^\w\u4e00-\u9fff]/g, " ")
      .split(/\s+/)
      .filter((t) => t.length >= 2);
  }

  private indexDocument(idx: number, content: string): void {
    const terms = this.tokenize(content);
    for (const term of terms) {
      if (!this.keywordIndex.has(term)) {
        this.keywordIndex.set(term, new Set());
      }
      this.keywordIndex.get(term)!.add(idx);
    }
  }
}

// ── 余弦相似度 ────────────────────────────────

function cosineSimilarity(a: number[], b: number[]): number {
  if (a.length !== b.length) return 0;
  let dot = 0, normA = 0, normB = 0;
  for (let i = 0; i < a.length; i++) {
    dot += a[i]! * b[i]!;
    normA += a[i]! ** 2;
    normB += b[i]! ** 2;
  }
  return dot / (Math.sqrt(normA) * Math.sqrt(normB) + 1e-10);
}

// ── 全局单例 ──────────────────────────────────

export const ragIndex = new RAGIndex();

/**
 * 工具调用系统 — Agent 可以真正执行操作
 *
 * 每个 Tool 有 name/description/parameters/execute，
 * Agent 通过 <tool_call> 标签触发工具调用。
 */

import { readFileSync, writeFileSync, mkdirSync, existsSync } from "fs";
import { execSync } from "child_process";
import { resolve } from "path";

// ── 工具定义 ──────────────────────────────────

export interface ToolDef {
  name: string;
  description: string;
  parameters: Array<{
    name: string;
    type: "string" | "number" | "boolean";
    description: string;
    required: boolean;
  }>;
  execute: (params: Record<string, unknown>) => Promise<ToolResult>;
}

export interface ToolResult {
  success: boolean;
  content: string;
  error?: string;
}

// ── 内置工具 ──────────────────────────────────

export const BUILTIN_TOOLS: ToolDef[] = [
  {
    name: "read_file",
    description: "读取项目中的代码文件",
    parameters: [
      { name: "path", type: "string", description: "文件路径（相对于项目根目录）", required: true },
    ],
    execute: async (params) => {
      const p = params["path"] as string;
      if (!existsSync(p)) return { success: false, content: "", error: `文件不存在: ${p}` };
      try {
        const content = readFileSync(p, "utf-8");
        return { success: true, content: content.slice(0, 3000) + (content.length > 3000 ? `\n... (共 ${content.length} 字符)` : "") };
      } catch (e) {
        return { success: false, content: "", error: String(e) };
      }
    },
  },
  {
    name: "write_file",
    description: "创建或覆盖代码文件",
    parameters: [
      { name: "path", type: "string", description: "文件路径", required: true },
      { name: "content", type: "string", description: "文件内容", required: true },
    ],
    execute: async (params) => {
      const p = params["path"] as string;
      const content = params["content"] as string;
      try {
        mkdirSync(resolve("."), { recursive: true });
        writeFileSync(p, content, "utf-8");
        return { success: true, content: `文件已写入: ${p} (${content.length} 字符)` };
      } catch (e) {
        return { success: false, content: "", error: String(e) };
      }
    },
  },
  {
    name: "run_command",
    description: "在项目目录运行 shell 命令（仅允许安全命令）",
    parameters: [
      { name: "command", type: "string", description: "要执行的命令（如 npm test, ls, cat）", required: true },
    ],
    execute: async (params) => {
      const cmd = (params["command"] as string).trim();
      // 安全校验：禁止危险命令
      const dangerous = [/rm -rf/, /del \//, /format/, />\/dev\/sd/, /:(){/, /curl.*\|.*sh/];
      for (const pattern of dangerous) {
        if (pattern.test(cmd)) {
          return { success: false, content: "", error: `命令被安全策略拦截: ${cmd}` };
        }
      }
      try {
        const result = execSync(cmd, { encoding: "utf-8", timeout: 10_000, cwd: process.cwd() });
        return { success: true, content: result.slice(0, 2000) };
      } catch (e: unknown) {
        const err = e as { stdout?: string; stderr?: string; message: string };
        return { success: false, content: err.stdout ?? "", error: err.stderr ?? err.message };
      }
    },
  },
  {
    name: "list_files",
    description: "列出项目目录中的文件",
    parameters: [
      { name: "path", type: "string", description: "目录路径，默认当前目录", required: false },
    ],
    execute: async (params) => {
      const p = (params["path"] as string) || ".";
      try {
        const { readdirSync } = require("fs");
        const files = readdirSync(p, { withFileTypes: true });
        const lines = files.map((f: { name: string; isDirectory: () => boolean }) =>
          f.isDirectory() ? `${f.name}/` : f.name
        );
        return { success: true, content: lines.slice(0, 50).join("\n") };
      } catch (e) {
        return { success: false, content: "", error: String(e) };
      }
    },
  },
];

// ── 工具执行器 ────────────────────────────────

export class ToolExecutor {
  private tools: Map<string, ToolDef>;

  constructor(tools: ToolDef[] = BUILTIN_TOOLS) {
    this.tools = new Map(tools.map((t) => [t.name, t]));
  }

  /** 注册新工具 */
  register(tool: ToolDef): void {
    this.tools.set(tool.name, tool);
  }

  /** 获取工具的 LLM 函数调用格式（OpenAI Function Calling 兼容） */
  getFunctionDefinitions(): Array<Record<string, unknown>> {
    return [...this.tools.values()].map((t) => ({
      type: "function",
      function: {
        name: t.name,
        description: t.description,
        parameters: {
          type: "object",
          properties: Object.fromEntries(
            t.parameters.map((p) => [p.name, { type: p.type, description: p.description }])
          ),
          required: t.parameters.filter((p) => p.required).map((p) => p.name),
        },
      },
    }));
  }

  /** 获取工具的文本描述（给不支持 Function Calling 的模型用） */
  getToolPrompt(): string {
    return [...this.tools.values()]
      .map((t) => {
        const params = t.parameters
          .map((p) => `  - ${p.name} (${p.type}${p.required ? ", 必填" : ""}): ${p.description}`)
          .join("\n");
        return `### ${t.name}\n${t.description}\n参数:\n${params}`;
      })
      .join("\n\n");
  }

  /** 解析 Agent 回复中的工具调用标签 */
  parseToolCalls(response: string): Array<{ name: string; params: Record<string, unknown> }> {
    const regex = /<tool_call\s+name=["'](\w+)["']>(.*?)<\/tool_call>/gs;
    const calls: Array<{ name: string; params: Record<string, unknown> }> = [];
    let match;
    while ((match = regex.exec(response)) !== null) {
      try {
        calls.push({
          name: match[1]!,
          params: JSON.parse(match[2]!) as Record<string, unknown>,
        });
      } catch {
        // 解析失败，忽略
      }
    }
    return calls;
  }

  /** 执行工具调用 */
  async execute(name: string, params: Record<string, unknown>): Promise<ToolResult> {
    const tool = this.tools.get(name);
    if (!tool) return { success: false, content: "", error: `未知工具: ${name}` };
    try {
      return await tool.execute(params);
    } catch (e) {
      return { success: false, content: "", error: String(e) };
    }
  }

  /** 执行 Agent 回复中的所有工具调用 */
  async executeAll(response: string): Promise<Array<{ name: string; result: ToolResult }>> {
    const calls = this.parseToolCalls(response);
    const results: Array<{ name: string; result: ToolResult }> = [];
    for (const call of calls) {
      results.push({ name: call.name, result: await this.execute(call.name, call.params) });
    }
    return results;
  }
}

/** 全局单例（含内置工具） */
export const toolExecutor = new ToolExecutor();

